#!/usr/bin/env python3
from pathlib import Path
from datetime import date
import json,csv,collections,sys
root=Path(__file__).resolve().parent
load=lambda n:json.loads((root/n).read_text(encoding='utf-8'))
def rows(n):
 with (root/n).open(encoding='utf-8',newline='') as f:return list(csv.DictReader(f,delimiter=';'))
checks=[]
def check(ok,desc):checks.append((bool(ok),desc));print(('PASS' if ok else 'FAIL'),desc)
expected={"README.md","CODEX_IMPORT.md","SCHEMA.json","survey_profiles.json","preference_matrix.csv","trips.json","destinations.json","activities.json","activities.csv","accommodations.json","accommodations.csv","transport.json","transport.csv","fare_rules.json","budget_scenarios.json","day_plans.json","food_evenings.json","sources.json","quality_issues.csv","validate.py"}
check({p.name for p in root.iterdir() if p.is_file()}==expected,'Exactly 20 files present')
survey=load('survey_profiles.json');trips=load('trips.json')['trips'];dest=load('destinations.json')['destinations'];acts=load('activities.json')['items'];acc=load('accommodations.json')['items'];trans=load('transport.json')['legs'];f=load('fare_rules.json');bud=load('budget_scenarios.json')['scenarios'];day=load('day_plans.json')['plans'];food=load('food_evenings.json')['items'];src=load('sources.json')['sources'];issues=rows('quality_issues.csv')
ids=lambda it:[x['id'] for x in it]
for name,coll in [('Trips',trips),('Destinations',dest),('Activities',acts),('Accommodations',acc),('Transport',trans),('Sources',src),('Fares',f['fares']),('Budget',bud),('Day plans',day),('Food',food)]:check(len(ids(coll))==len(set(ids(coll))),f'{name} IDs unique')
check(len(trips)==4,'Four Tripsy variants')
check(len(survey['participants'])==3,'Three survey respondents')
check(len({x['id'] for x in survey['participants']})==3,'Respondents unique')
check(all(x['hard_lodging_cap_eur'] is None for x in survey['participants']),'No fabricated hard lodging caps')
check(all(x['age_at_trip']==18 for x in survey['participants']),'All survey ages 18')
check(all(all(isinstance(v,int) and 0<=v<=5 for v in x['preferences_0_to_5'].values()) for x in survey['participants']),'Survey 0-5 range')
check(len(rows('preference_matrix.csv'))==len(survey['participants'][0]['preferences_0_to_5']),'Preference matrix complete')
check({t['party_size'] for t in trips}=={3,4},'Distinct 3/4 guest groups')
check(next(t for t in trips if t['id']=='swiss-week')['members'][-1]=='swiss_guest_4_unknown','Fourth Swiss traveler not assigned a fabricated profile')
check({t['tripsy_id'] for t in trips}=={'1297194','1312180','1275516','1273324'},'All original Tripsy IDs retained')
check(all(date.fromisoformat(t['start'])<date.fromisoformat(t['end']) for t in trips),'Trip dates valid')
check(all(t['original_is_read_only'] for t in trips),'Trip originals marked read-only')
check(all(all(s['destination_id'] in ids(dest) for s in t['stays']) for t in trips),'Stay destinations valid')
check(all(date.fromisoformat(s['checkin'])<date.fromisoformat(s['checkout']) for t in trips for s in t['stays']),'Stay dates valid')
check(all(a['destination_id'] in ids(dest) for a in acts+acc+food),'Candidate destinations valid')
check(all(a['booking_status']=='not_booked' and a['selected'] is False for a in acts+acc),'No candidate marked selected/booked')
check(all(a['cost']['amount_minor'] is None or a['cost']['amount_minor']>=0 for a in acts),'Activity price null or nonnegative')
check(all(0<=a['group_score_0_100']<=100 for a in acts if a['group_score_0_100'] is not None),'Group activity scores 0-100')
check(all(a['latitude'] is None and a['longitude'] is None for a in acts),'No fabricated exact activity coordinates')
check(all(a['price']['total_minor']>0 and a['price']['currency']=='EUR' for a in acc),'Accommodation quote amounts valid')
check(all(a['price']['quoted_on']=='2026-11-13' for a in acc),'Fresh quote date')
check(all(a['price']['taxes_and_local_fees_complete'] is None for a in acc),'Final fees explicitly unverified')
check(all(not a['beds_for_group_verified'] for a in acc),'Beds not claimed confirmed')
check(all(a['guests']==(4 if 'swiss-week' in a['trip_context'] else 3) for a in acc),'Guest counts align by trip')
check(all(date.fromisoformat(a['checkout'])>date.fromisoformat(a['checkin']) for a in acc),'Accommodation check-outs after check-ins')
check(all(s['from_destination_id'] in ids(dest) and s['to_destination_id'] in ids(dest) for s in trans),'Transport places valid')
check(all(s['trip_id'] in ids(trips) for s in trans),'Transport references trips')
check(all(s['departure_local'] is None and s['arrival_local'] is None and s['ticket_price_minor'] is None for s in trans),'No invented 2027 schedules or ticket prices')
check(all(s['seat_booking_status']=='unbooked' for s in trans),'No invented rail bookings')
check(all(s['source_ids'] and set(s['source_ids']).issubset(ids(src)) for s in trans),'Transport sources valid')
check(all(set(a['source_ids']).issubset(ids(src)) for a in acts+acc),'Candidate sources valid')
check(all(set(x['sources']).issubset(ids(src)) for x in f['fares']),'Fare sources valid')
check(all(x['source_id'] in ids(src) for x in issues),'Issue sources valid')
check(all(all(aid in ids(acts) for aid in p['activity_option_ids_ordered']) for p in day),'Day plan activity links valid')
check(all(p['proposal_not_active'] and not p['change_original_tripsy_trip'] for p in day),'Day plans unselected')
check(all(b['status'].startswith('hypothetical_') for b in bud),'Budgets comparisons only')
check(all(all(aid in ids(acc) for aid in b['candidate_lodging_ids']) for b in bud),'Budget lodging foreign keys valid')
check(all(sum(b['per_person_split_minor'].values())==b['total_group_minor'] for b in bud if b['total_group_minor'] is not None),'Per-person trip costs add to total cents')
check(all(sum(b['per_person_lodging_split_minor'].values())==b['group_cost_minor']['accommodation'] for b in bud if b['total_group_minor'] is None),'Swiss lodging cents add exactly')
check(all(b['group_cost_minor']['accommodation']==sum(next(x['price']['total_minor'] for x in acc if x['id']==iid) for iid in b['candidate_lodging_ids']) for b in bud),'No duplicate lodging item in budget scenarios')
check(all(a['booking_url'].startswith('https://www.booking.com/hotel/') for a in acc),'All accommodation links are provider property URLs')
check(all(len(rows(csvfile))==len(data) for csvfile,data in [('activities.csv',acts),('accommodations.csv',acc),('transport.csv',trans)]),'CSV/JSON row count alignment')
check(10000//3*3+10000%3==10000,'Cents split 100.00 EUR across 3')
check(10000//3+1==3334 and 10000//3==3333,'Residual cent gets deterministic allocation')
check(len(issues)>=20,'Actionable research backlog')
print(f'\nVALIDATION: {sum(o for o,_ in checks)}/{len(checks)} checks passed; activities={len(acts)}, lodgings={len(acc)}, transport={len(trans)}')
sys.exit(0 if all(ok for ok,_ in checks) else 1)